const raw = $input.first().json;
const body = raw.body || raw;

const event = body.event || body.message?.event || '';
const msg = body.message || body;
const attEarly = msg.attachments || body.attachments || [];
const attEarlyList = Array.isArray(attEarly) ? attEarly : [];

if (event && !String(event).includes('message_created') && event !== 'message_updated') {
  if (!msg.content && !msg.content_type && !body.content && attEarlyList.length === 0) return [];
}

const message = (body.content !== undefined && body.conversation) ? body : msg;
const conversation = message.conversation || body.conversation || {};
const account = message.account || body.account || {};
const sender = message.sender || conversation.meta?.sender || {};

const messageType = message.message_type;
const isIncoming = messageType === 0 || messageType === 'incoming' || messageType === 'Incoming';
const isPrivate = message.private === true;
const senderType = (sender.type || '').toLowerCase();

if (isPrivate) return [];
if (messageType === 1 || messageType === 'outgoing' || messageType === 'Outgoing') return [];
if (senderType === 'user' || senderType === 'agent_bot') return [];
if (messageType !== undefined && messageType !== null && !isIncoming && messageType !== 'incoming') return [];

const assignee = conversation.meta?.assignee;
const assigneeType = String(conversation.meta?.assignee_type || assignee?.type || '').toLowerCase();
const teamId = conversation.team_id || conversation.cached_team_id || conversation.meta?.team?.id;
const isBotAssignee = assigneeType.includes('bot') || assigneeType === 'agentbot';
const humanAssigned =
  (conversation.assignee_id && !isBotAssignee) ||
  (assignee && String(assignee.type || '').toLowerCase() === 'user');
if (humanAssigned || teamId) return [];

let phone = sender.phone_number || conversation.meta?.sender?.phone_number || conversation.contact_inbox?.source_id || '';
phone = String(phone).replace(/\s+/g, '').replace(/^\+/, '');
if (phone.startsWith('549')) phone = '54' + phone.slice(3);

function fold(s) {
  return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const attachments = message.attachments || body.attachments || attEarlyList;
const attList = Array.isArray(attachments) ? attachments : [];
const MEDIA_FILE = new Set(['image', 'audio', 'video', 'file', 'ig_reel', 'story_mention']);
function attKind(a) {
  const ft = String(a.file_type || a.fileType || '').toLowerCase();
  const ct = String(a.content_type || a.contentType || a.mime_type || '').toLowerCase();
  if (ft === 'image' || ct.startsWith('image/')) return 'imagen';
  if (ft === 'audio' || ct.startsWith('audio/')) return 'audio';
  if (ft === 'video' || ft === 'ig_reel' || ct.startsWith('video/')) return 'video';
  if (ft === 'file' || ct === 'application/pdf' || ct.includes('octet-stream')) return 'archivo';
  if (MEDIA_FILE.has(ft)) return ft;
  if (ct) return 'archivo';
  return '';
}
const mediaKinds = attList.map(attKind).filter(Boolean);
const hasMedia = mediaKinds.length > 0;
const media_kind = (mediaKinds.includes('imagen') && mediaKinds.includes('audio'))
  ? 'imagen/audio'
  : (mediaKinds[0] || '');

let texto = String(message.content || '').trim();
const lines = texto.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const last = lines.length ? lines[lines.length - 1] : texto;

let boton_id = '';
const ca = message.content_attributes || {};
const submitted = ca.submitted_values || ca.items || [];
if (Array.isArray(submitted) && submitted.length) {
  const v = submitted[0];
  boton_id = String(v.value || v.id || '');
  if (!texto) texto = String(v.title ?? v.value ?? '');
}
if (!boton_id && ca.submitted_values && typeof ca.submitted_values === 'object' && !Array.isArray(ca.submitted_values)) {
  boton_id = String(ca.submitted_values.value || '');
}

const quoteBits = [];
const replyId = ca.in_reply_to || ca.in_reply_to_id || message.in_reply_to || '';
const convMsgs = conversation.messages || body.conversation?.messages || [];
if (replyId && Array.isArray(convMsgs)) {
  const quoted = convMsgs.find(m => String(m.id) === String(replyId) || String(m.source_id || '') === String(ca.in_reply_to_external_id || ''));
  if (quoted && quoted.content) quoteBits.push(String(quoted.content));
}
for (const k of ['in_reply_to_content', 'quoted_content', 'quoted_message']) {
  const v = ca[k];
  if (typeof v === 'string' && v.trim()) quoteBits.push(v);
  else if (v && typeof v === 'object' && v.content) quoteBits.push(String(v.content));
}
if (quoteBits.length) texto = quoteBits.join('\n') + '\n' + texto;
if (replyId) texto += '\n__cw_in_reply_to__:' + replyId;

const titleMap = {
  'horarios de clinica': 'horarios_clinica',
  'horarios clinica': 'horarios_clinica',
  'sacar un turno': 'quiero_turno',
  'volver al menu': 'volver_menu',
  'volver': 'volver_menu',
  'menu': 'volver_menu',
  'repetir pregunta': 'repetir_pregunta',
  'repetir': 'repetir_pregunta',
  'cancelar turno': 'cancelar_turno_pedido',
  'si, cancelar': 'cancel_si',
  'si cancelar': 'cancel_si',
  'no, continuar': 'cancel_no',
  'no continuar': 'cancel_no',
  'cualquier doctor': 'medico_cualquiera',
  'mi medico de cabecera': 'medico_cabecera',
  'otra / particular': 'obra_otra',
  'otra': 'obra_otra',
  'otras': 'obra_otra',
  'particular': 'obra_particular',
  'sin obra': 'obra_particular',
  'sin obras': 'obra_particular',
  'sin obra social': 'obra_particular',
  'sin obras sociales': 'obra_particular',
  'particular/sin obra social': 'obra_particular',
  'particular / sin obra social': 'obra_particular',
  'particular sin obra': 'obra_particular',
  'particular sin obra social': 'obra_particular',
  'no tengo obra': 'obra_particular',
  'no tengo obra social': 'obra_particular',
  'no tengo obras sociales': 'obra_particular',
  'como particular': 'obra_particular',
  'soy particular': 'obra_particular',
  'voy particular': 'obra_particular',
  'voy como particular': 'obra_particular',
  'pago particular': 'obra_particular',
  'paciente particular': 'obra_particular',
  'consulta particular': 'obra_particular',
  'obra particular': 'obra_particular',
  'sin cobertura': 'obra_particular',
  'no tengo cobertura': 'obra_particular',
  'ninguna obra': 'obra_particular',
  'ninguna obra social': 'obra_particular',
  'no tengo': 'obra_particular',
  'confirmar': 'confirmar_turno',
  'continuar consulta': 'continuar_consulta',
  'hablar secretaria': 'hablar_secretaria',
  'hablar con secretaria': 'hablar_secretaria',
  'hacer otra consulta': 'otra_consulta',
  'otra consulta': 'otra_consulta',
};

if (Array.isArray(submitted) && submitted.length && !boton_id) {
  const t = fold(submitted[0].title || '');
  if (titleMap[t]) boton_id = titleMap[t];
}

if (!boton_id) {
  boton_id = titleMap[fold(last)] || '';
}
if (!boton_id) {
  const navIds = new Set(['repetir_pregunta', 'cancelar_turno_pedido', 'cancel_si', 'cancel_no', 'volver_menu', 'confirmar_turno', 'continuar_consulta', 'hablar_secretaria', 'otra_consulta']);
  for (const c of lines) {
    const mapped = titleMap[fold(c)];
    if (mapped && navIds.has(mapped)) { boton_id = mapped; break; }
  }
}

if (!phone && !conversation.id && !conversation.display_id) return [];

const conversationId = conversation.display_id || conversation.id || body.conversation_id; // Chatwoot API path uses display_id
const accountId = conversation.account_id || account.id || body.account?.id || body.account_id;

let tipo = boton_id ? 'interactive' : 'text';
if (hasMedia) tipo = 'media';

return [{
  json: {
    telefono: phone || String(conversationId),
    tipo,
    texto: texto || '',
    boton_id: boton_id || '',
    conversation_id: conversationId,
    account_id: accountId,
    media_kind,
  }
}];

const n = $('Normalize Message').first().json;
const row = $input.first().json;
let ctx = row.context ?? {};
if (typeof ctx === 'string') {
  try { ctx = JSON.parse(ctx); } catch (e) { ctx = {}; }
}
function fold(s) {
  return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
const PREV_STEP = {
  awaiting_dni: 'awaiting_nombre',
  awaiting_obra_social: 'awaiting_dni',
  awaiting_obra_social_otra: 'awaiting_obra_social',
  awaiting_telefono: 'awaiting_obra_social',
  awaiting_medico: 'awaiting_obra_social',
  awaiting_dia_hora: 'awaiting_medico',
  awaiting_confirmacion: 'awaiting_dia_hora',
};
const CURRENT_KW = {
  awaiting_nombre: /nombre completo/,
  awaiting_dni: /dni/,
  awaiting_obra_social: /obra social/,
  awaiting_obra_social_otra: /nombre de tu obra social/,
  awaiting_telefono: /telefono/,
  awaiting_medico: /medico preferis|que medico/,
  awaiting_dia_hora: /horario preferis/,
  awaiting_confirmacion: /confirmas el turno/,
};
function quotedStep(texto) {
  const f = fold(texto);
  if (/confirmas el turno/.test(f)) return 'awaiting_confirmacion';
  if (/nombre completo/.test(f)) return 'awaiting_nombre';
  if (/cual es tu dni|tu dni|\bdni\b/.test(f)) return 'awaiting_dni';
  if (/nombre de tu obra social/.test(f)) return 'awaiting_obra_social_otra';
  if (/obra social/.test(f)) return 'awaiting_obra_social';
  if (/numero de telefono/.test(f)) return 'awaiting_telefono';
  if (/medico preferis|que medico/.test(f)) return 'awaiting_medico';
  if (/horario preferis/.test(f)) return 'awaiting_dia_hora';
  return null;
}
let estado = row.state || 'idle';
const boton = String(n.boton_id || '').trim();
const texto = String(n.texto || '').replace(/\n?__cw_in_reply_to__:\S+/g, '').trim();
const lines = texto.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const last = lines.length ? lines[lines.length - 1] : texto;
const isRepetir = boton === 'repetir_pregunta'
  || /^(repetir|repetir pregunta)$/i.test(fold(last))
  || lines.some(l => /^(repetir|repetir pregunta)$/i.test(fold(l)));
if (isRepetir && /^awaiting_/.test(estado)) {
  let q = quotedStep(texto);
  if (!q) {
    const kw = CURRENT_KW[estado];
    if (!kw || !kw.test(fold(texto))) q = PREV_STEP[estado] || null;
  }
  if (q) {
    const order = ['awaiting_nombre','awaiting_dni','awaiting_obra_social','awaiting_obra_social_otra','awaiting_telefono','awaiting_medico','awaiting_dia_hora','awaiting_confirmacion'];
    const cur = order.indexOf(estado);
    const tgt = order.indexOf(q);
    if (tgt >= 0 && (cur < 0 || tgt <= cur)) estado = q;
  }
}
return [{
  json: {
    telefono: n.telefono,
    tipo: n.tipo,
    texto: n.texto,
    boton_id: n.boton_id,
    conversation_id: n.conversation_id,
    account_id: n.account_id,
    estado,
    datos_json: ctx,
    context: ctx,
    pending_prompt: ctx.pending_prompt || '',
    handoff_reason: ctx.handoff_reason || '',
    handoff_quote: ctx.handoff_quote || '',
    media_kind: n.media_kind || '',
  }
}];

const item = $input.first().json;
let estado = item.estado || 'idle';
let boton = String(item.boton_id || '').trim();
const texto = String(item.texto || '').trim();
const lines = texto.split(/\r?\n/).map(x => x.trim()).filter(Boolean);
const last = lines.length ? lines[lines.length - 1] : texto;
const lastLower = last.toLowerCase();
const onMenu = estado === 'idle' || estado === 'menu_shown';
const ctx = item.context && typeof item.context === 'object' ? item.context : {};

function fold(s) {
  return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function sqlStr(s) {
  return String(s || '').replace(/\0/g, '').replace(/[\r\n]+/g, ' ').replace(/'/g, "''").slice(0, 400);
}
function isEstudioIntent(t) {
  const f = fold(t);
  if (!f) return false;
  if (/(consult|pregunt|\binfo\b|informacion).{0,60}(tratamiento|estudio|cirugia)/.test(f)) return true;
  if (/(tratamiento|estudio|cirugia).{0,60}(consult|pregunt|\binfo\b|informacion)/.test(f)) return true;
  if (/cuanto sale|cuanto cuesta|\bprecio\b|\bvalor\b|se cobra|\bcobran\b|cubre la obra/.test(f)) return true;
  if (/\bcampo visual\b/.test(f)) return true;
  if (/\bperimetria(\s+computarizada)?\b/.test(f)) return true;
  if (/\btopografia\b/.test(f)) return true;
  if (/\bpaquimetria\b/.test(f)) return true;
  if (/\bretinografia(\s+digital)?\b/.test(f)) return true;
  if (/\boct\s+(anterior|posterior)\b/.test(f)) return true;
  if (/\bocta\b/.test(f)) return true;
  if (/\boct\b/.test(f)) return true;
  if (/\bangiografia\b/.test(f)) return true;
  if (/\bmicroscopia especular\b/.test(f)) return true;
  return false;
}
function isSecretariaIntent(t) {
  const f = fold(t);
  if (!f) return false;
  if (/^para poder responder mejor esta consulta/.test(f)) return false;
  if (/hablar con (una )?secretaria/.test(f)) return true;
  if (/(pasar|derivar|comunicar|conectar).{0,40}(con )?(una )?(persona|humano|humana|secretaria|alguien|operador)/.test(f)) return true;
  if (/(quiero|necesito|preciso).{0,40}secretaria/.test(f)) return true;
  if (/(quiero|necesito|preciso).{0,40}(persona|humano|humana|atencion humana)/.test(f)) return true;
  if (/\b(atencion humana|persona real|operador humano)\b/.test(f)) return true;
  return false;
}
function wantsHandoffIntent(t) {
  return isSecretariaIntent(t) || isEstudioIntent(t);
}

const lastFold = lastLower.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const allFold = fold(texto);
const handoffProbe = last.replace(/\n?__cw_in_reply_to__:\S+/g, '').trim() || texto;
const pending = String(item.pending_prompt || ctx.pending_prompt || '');
const quotedMedia = /no podemos recibir fotos ni audios/.test(allFold);
const quotedEstudio = /necesitamos derivarlo con una secretaria/.test(allFold);
const fromMediaPrompt = pending === 'media_warn' || quotedMedia;
const fromEstudioPrompt = pending === 'estudio_handoff' || quotedEstudio;

if (!boton && (fromMediaPrompt || fromEstudioPrompt)) {
  if (fromMediaPrompt && lastFold === '1') boton = 'continuar_consulta';
  else if (fromMediaPrompt && lastFold === '2') boton = 'hablar_secretaria';
  else if (fromEstudioPrompt && lastFold === '1') boton = 'hablar_secretaria';
  else if (fromEstudioPrompt && lastFold === '2') boton = 'otra_consulta';
}

const cancelKw = boton === 'cancelar_turno_pedido' || boton === 'cancelar_turno'
  || /^(cancelar|salir|menu|menú)$/i.test(lastLower)
  || /^cancelar turno$/i.test(lastLower);
const isAwaiting = /^awaiting_/.test(estado);
const yes = boton === 'cancel_si' || /^(si|sí)$/i.test(lastLower) || /sí,? cancelar/i.test(lastLower) || /si,? cancelar/i.test(lastLower);
const no = boton === 'cancel_no' || /^no$/i.test(lastLower) || /no,? continuar/i.test(lastLower);
const isRepetir = boton === 'repetir_pregunta' || /^(repetir|repetir pregunta)$/i.test(lastLower) || lines.some(l => /^(repetir|repetir pregunta)$/i.test(l));
const numericMenu = onMenu && !fromMediaPrompt && !fromEstudioPrompt;
const isHorarios = boton === 'horarios_clinica'
  || (onMenu && /^(horarios|horarios( de( la)?)? clinica)$/i.test(lastFold))
  || (numericMenu && lastFold === '1');
const isTurno = boton === 'quiero_turno' || boton === 'confirmar_turno'
  || (numericMenu && lastFold === '2')
  || (onMenu && /\bturn[oaie]s?\b|\bcitas?\b|sacar\s+(un\s+)?turn/i.test(lastFold));
const isMenuKw = boton === 'volver_menu'
  || /^(menu|volver|volver al menu)$/i.test(lastFold);
const isGreeting = /^(hola+|holis|buenas|buenos|buen[oa]s?( (dias|tardes|noches))?|hi|hey|hello|que tal)$/i.test(lastFold);
const isHablar = boton === 'hablar_secretaria';
const isContinuar = boton === 'continuar_consulta';
const isOtra = boton === 'otra_consulta';
const isMedia = item.tipo === 'media';
const wantsHandoff = wantsHandoffIntent(last) || wantsHandoffIntent(handoffProbe) || wantsHandoffIntent(allFold);

let route = 'welcome';
let handoff_reason = String(item.handoff_reason || ctx.handoff_reason || '');
let handoff_quote = String(item.handoff_quote || ctx.handoff_quote || '');

if (estado === 'confirmando_cancelacion') {
  if (yes) route = 'cancel_yes';
  else if (no) route = 'cancel_no';
  else if (isMedia) route = 'media_warn';
  else route = 'cancel_ask';
} else if (isMedia) {
  route = 'media_warn';
} else if (cancelKw && isAwaiting) {
  route = 'cancel_ask';
} else if (isRepetir && isAwaiting) {
  route = 'booking';
} else if (isHorarios) {
  route = 'horarios';
} else if (isMenuKw || isGreeting) {
  route = 'welcome';
} else if (isTurno) {
  route = 'booking';
} else if (isHablar) {
  route = 'hablar_secretaria';
} else if (isContinuar) {
  route = isAwaiting ? 'booking' : 'welcome';
} else if (isOtra) {
  route = 'welcome';
} else if (wantsHandoff) {
  route = 'estudio_handoff';
} else if (isAwaiting) {
  route = 'booking';
} else if (estado === 'menu_shown' && texto && !boton) {
  route = 'faq';
} else {
  route = 'welcome';
}

if (route === 'media_warn') {
  handoff_reason = 'imagen/audio';
  const cap = last.replace(/\n?__cw_in_reply_to__:\S+/g, '').trim();
  handoff_quote = cap || ('[' + (item.media_kind || 'imagen/audio') + ']');
} else if (route === 'estudio_handoff') {
  const est = isEstudioIntent(last) || isEstudioIntent(handoffProbe) || isEstudioIntent(allFold);
  const sec = isSecretariaIntent(last) || isSecretariaIntent(handoffProbe) || isSecretariaIntent(allFold);
  handoff_reason = est ? 'estudio/precio' : (sec ? 'solicitud_secretaria' : 'estudio/precio');
  handoff_quote = handoffProbe || texto;
} else if (route === 'hablar_secretaria') {
  if (!handoff_reason) {
    if (fromMediaPrompt || pending === 'media_warn') handoff_reason = 'imagen/audio';
    else handoff_reason = 'estudio/precio';
  }
  if (!handoff_quote) {
    handoff_quote = last.replace(/\n?__cw_in_reply_to__:\S+/g, '').trim();
  }
}

return [{ json: { ...item, estado, texto, last_line: last, boton_id: boton, route, handoff_reason, handoff_quote, handoff_quote_sql: sqlStr(handoff_quote) } }];

const m = $('Merge Context').first().json;
const s = $input.first().json;
const content = `🕘 *Nuestros horarios:*
- ${s.clinic_hours || ''}
Estamos ubicados en 📍 ${s.address || ''}

Podés escribir:
2) Sacar un turno
o "menú" para volver.`;
return [{
  json: {
    conversation_id: m.conversation_id,
    account_id: m.account_id,
    cw_body: {
      content,
      message_type: 'outgoing',
      private: false,
      content_type: 'text'
    }
  }
}];

const m = $('Merge Context').first().json;
return [{
  json: {
    conversation_id: m.conversation_id,
    account_id: m.account_id,
    cw_body: {
      content: '¿Seguro que querés cancelar el turno?',
      message_type: 'outgoing',
      private: false,
      content_type: 'input_select',
      content_attributes: {
        items: [
          { title: 'Sí, cancelar', value: 'cancel_si' },
          { title: 'No, continuar', value: 'cancel_no' }
        ]
      }
    }
  }
}];

